class Solution {
public:
    int paintWalls(vector<int>& cost, vector<int>& time) {
        int n = cost.size();
        const int INF = 1e9;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            int c = time[i] + 1;
            for (int j = n; j >= 1; j--) {
                int prev = max(0, j - c);
                dp[j] = min(dp[j], dp[prev] + cost[i]);
            }
        }
        return dp[n];
    }
};
